%[text] # BC121 rear chamber volume study
%[text] **J.G. Vermond, JVsound**
%[text] Prepared on 2026-10-16. The closed rear chamber of the cabinet is about 109 L in the model. This script compares the harmonic acoustics results of configuration A for rear chamber volumes of 80, 90, 100 and 110 L (exports in `Simulation\RearChamberVolumeStudy`) and shows the effect on the pressure on the diaphragm and on the SPL at the 10 m microphone.
%%
%[text] ## Settings
volumes = [80 90 100 110]; % Rear chamber volumes in [L]
micName = "Mic10m"; % Far-field microphone outside the mesh
sourceVoltage = 28.3; % RMS voltage of the amplifier in [V]
diaphragmVelocity = 1e-3; % Velocity imposed on the diaphragm in the FEA model in [m/s]
pRef = 20e-6; % Reference pressure for the SPL in [Pa]
studyFolder = fullfile(currentProject().RootFolder,"Simulation","RearChamberVolumeStudy");
volumeLabels = volumes + " L";
numVolume = numel(volumes);
splUnit = "dB re 20 " + char(181) + "Pa";
%%
%[text] ## Read the FEA results
%[text] Mechanical exports the pressure in MPa; it is converted to Pa. The far-field pressure is the amplitude and phase file of the microphone, combined by `readFarField`. The file names carry the volume as suffix (for example `Frequency Response Rear 80L.txt`).
readExport = @(file) readmatrix(file,FileType="text",NumHeaderLines=1);
pFront = []; pRear = []; pFar = [];
for v = 1:numVolume
    tag = volumes(v) + "L";
    front = readExport(fullfile(studyFolder,"Frequency Response Front " + tag + ".txt"));
    rear = readExport(fullfile(studyFolder,"Frequency Response Rear " + tag + ".txt"));
    amplitude = readExport(fullfile(studyFolder,"Far-field Maximum Pressure " + micName + " " + tag + ".txt"));
    phase = readExport(fullfile(studyFolder,"Far-field Phase " + micName + " " + tag + ".txt"));
    if v == 1
        frequency = front(:,1);
    end
    sameFrequency = @(x) size(x,1) == numel(frequency) && max(abs(x(:,1) - frequency)) < 1e-3*max(frequency);
    assert(sameFrequency(front) && sameFrequency(rear) && sameFrequency(amplitude) && sameFrequency(phase), ...
        "Volume %g L has other frequencies than volume %g L.",volumes(v),volumes(1))
    pFront(:,v) = (front(:,4) + 1i*front(:,5))*1e6; %#ok<SAGROW>
    pRear(:,v) = (rear(:,4) + 1i*rear(:,5))*1e6; %#ok<SAGROW>
    pFar(:,v) = amplitude(:,2)*1e6.*exp(1i*deg2rad(phase(:,2))); %#ok<SAGROW>
end
disp("Volumes read: " + join(volumeLabels,", ")) %[output:5e5f8486]
%%
%[text] ## Pressure on the diaphragm
%[text] The rear pressure is the load of the closed chamber: a smaller chamber is stiffer and gives a higher pressure. The front pressure is the load of the horn and should hardly depend on the rear volume.
tiledlayout(2,1) %[output:32f117b2]
nexttile %[output:32f117b2]
loglog(frequency,abs(pFront)), grid on %[output:32f117b2]
ylabel("Pressure (Pa)"), legend(volumeLabels,Location="best"), title("Front of the diaphragm") %[output:32f117b2]
nexttile %[output:32f117b2]
loglog(frequency,abs(pRear)), grid on %[output:32f117b2]
xlabel("Frequency (Hz)"), ylabel("Pressure (Pa)"), title("Rear of the diaphragm") %[output:32f117b2]
%%
%[text] ## Calculate the SPL with the loudspeaker system
%[text] Same driver and `comp.FeaEnclosure` set-up as in `ConfigurationAMeshStudy`: the averaged pressures on the diaphragm load the driver and the far-field pressure gives the transfer to the microphone.
asData = @(p) struct(Frequency=frequency.',Pressure=p.');
splFar = zeros(numel(frequency),numVolume);
for v = 1:numVolume
    sys = lspsys;
    sys.SourceVoltage = sourceVoltage;
    sys.Enclosure = comp.FeaEnclosure;
    sys.Enclosure.PressureFront = asData(pFront(:,v));
    sys.Enclosure.PressureRear = asData(pRear(:,v));
    sys.Enclosure.DiaphragmVelocity = diaphragmVelocity;
    sys.Enclosure.Driver = comp.Driver;
    sys.Enclosure.Driver.Re = 6;
    sys.Enclosure.Driver.Le = 2.2e-3;
    sys.Enclosure.Driver.Qes = 0.38;
    sys.Enclosure.Driver.Qms = 6.4;
    sys.Enclosure.Driver.Fs = 32;
    sys.Enclosure.Driver.Sd = 1680e-4;
    sys.Enclosure.Driver.Vas = 200e-3;
    sys.Enclosure.Driver.Znom = 8;
    sys.Enclosure.Driver.Zmin = 7;
    sys.Enclosure.Driver.Pnom = 2000;
    sys.Enclosure.Driver.Xvar = 16e-3;
    sys.Frequency = sys.Enclosure.Frequency;
    sys.Enclosure.PressureFarField = asData(pFar(:,v));
    res = sys.createResult;
    results(v) = res; %#ok<SAGROW>
    splFar(:,v) = res.SoundPressureLevel(:);
end
%%
%[text] ## SPL at 10 m
figure %[output:4316b8db]
for v = 1:numVolume
    plot(results(v),"SoundPressureLevel"); hold on %[output:4316b8db]
end
hold off %[output:4316b8db]
legend(volumeLabels,Location="best") %[output:4316b8db]
title("SPL at 10 m, " + sourceVoltage + " V RMS") %[output:4316b8db]
%%
%[text] ## Maximum SPL at 10 m
%[text] The highest SPL that the power and the excursion limits of the driver allow, for a sine signal (`splMax` of the result, plotted with `plot(res,"splMax")` of the toolbox).
figure %[output:154ef176]
for v = 1:numVolume
    plot(results(v),"splMax"); hold on %[output:154ef176]
end
hold off %[output:154ef176]
legend(volumeLabels,Location="best") %[output:154ef176]
title("Maximum SPL at 10 m") %[output:154ef176]
%%
%[text] ## Summary
%[text] Per volume: SPL at the peak of the 10 m response below `bandLimit` (the subwoofer band; the response above it is dominated by resonances in the model), its frequency, and the -3 dB band edges relative to that peak (first and last frequency above the -3 dB level).
bandLimit = 200; % Upper limit of the subwoofer band in [Hz]
peakSpl = zeros(numVolume,1); peakFrequency = zeros(numVolume,1);
f3Low = zeros(numVolume,1); f3High = zeros(numVolume,1);
inBand = frequency <= bandLimit;
for v = 1:numVolume
    level = splFar(:,v);
    level(~inBand) = -inf;
    [peakSpl(v),i] = max(level);
    peakFrequency(v) = frequency(i);
    above = find(level >= peakSpl(v) - 3);
    f3Low(v) = frequency(above(1));
    f3High(v) = frequency(above(end));
end
summary = table(volumes.',peakSpl,peakFrequency,f3Low,f3High, ...
    VariableNames=["Volume (L)" "Peak SPL (dB)" "Peak frequency (Hz)" "f-3dB low (Hz)" "f-3dB high (Hz)"]);
disp(summary) %[output:8edc264b]

